// The output of a passing command that the summary prints, when the output is short.

import { MAX_PASS_OUTPUT_LINES } from "../limits.ts";
import { cut, nonBlankLines } from "./failures.ts";

/**
 * The lines of `output` to print for a passing command, or `null` when the output has no line or more than `MAX_PASS_OUTPUT_LINES` lines.
 * A long output stays in the log file, so a long test run does not fill the context.
 */
export const passOutput = (output: string): readonly string[] | null => {
  const lines = nonBlankLines(output);
  if (lines.length === 0 || lines.length > MAX_PASS_OUTPUT_LINES) return null;
  return lines.map(cut);
};
